{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 detailed monitoring is disabled",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The instance does not enable detailed monitoring, reducing the granularity of CloudWatch metrics available for security monitoring and incident investigation."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "EC2 Instance Metadata Service v1 is enabled",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "No metadata options require IMDSv2, so the instance can accept less secure IMDSv1 requests and is more exposed to credential theft through SSRF-style attacks."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "EC2 root EBS volume is not explicitly encrypted",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The root block device does not explicitly enable encryption, so data at rest may be unencrypted when account-level EBS encryption by default is not configured."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t2.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n  monitoring             = true\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}\n",
  "fix_summary": "Enabled detailed CloudWatch monitoring, enforced IMDSv2, and encrypted the instance root EBS volume. EBS optimization was not enabled because it is a performance setting and may not be supported by t2.micro; no IAM role was added because this file shows no need for AWS API permissions."
}
